import { Component, createEffect, createSignal, For, onCleanup, onMount, ParentComponent, useContext } from "solid-js";

import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { FiligreeTitle } from "#core/ui-next/components/filigree-title.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Panel, PanelProps } from "#core/ui-next/components/panel.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { NestedTooltipContext } from "#core/ui-next/components/tooltip-nested.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { isMobile } from "#core/ui-next/services/view-experience.js";

import { SyncCard } from "#base/ui/syncretism/syncretism-card.jsx";
import { SyncretismConfirm } from "#base/ui/syncretism/syncretism-confirm.jsx";

import style from "./screen-syncretism.scss?url";
import { SyncretismScreenModel, SyncretismScreenModelContext } from "./syncretism-screen-model.js";

const SyncretismStartScreen: ParentComponent<PanelProps> = (props) => {
	const model = SyncretismScreenModel.get();
	const [civName, setCivName] = createSignal<string>("");
	const [civPeopleName, setCivPeopleName] = createSignal<string>("");
	const hotkeyContext = useContext(HotkeyContext);
	const audio = useAudio();

	onMount(() => {
		hotkeyContext.registerNavtray("cancel", "LOC_GENERIC_BACK");
		hotkeyContext.registerNavtray("accept", "LOC_GENERIC_SELECT");
		if (!model.isFirstSeen) {
			model.isFirstSeen = true;
			audio("popup-open");
		}
	});

	onCleanup(() => {
		hotkeyContext.unregisterNavtray("cancel");
		hotkeyContext.unregisterNavtray("accept");
	});

	createEffect(() => {
		const player = Players.get(GameContext.localPlayerID);
		if (!player) {
			return;
		}
		const civDefinition = GameInfo.Civilizations.lookup(player.civilizationType);
		if (!civDefinition) {
			return;
		}
		setCivPeopleName(civDefinition.Adjective);
		setCivName(civDefinition.Name);
	});

	return (
		<div class={"size-full flex flex-col flex-auto px-3 py-5 relative"}>
			<FiligreeTitle.Accent
				text={props.name}
				textClass="text-2xl"
				class="p-2 mt-3 mb-2 pointer-events-none flex-auto max-h-24 font-bold text-shadow-subtle"
			/>
			<div class={`w-full mt-2 mb-2 ${model.isSmallScreen() ? "px-4" : "px-20"}`}>
				<div
					class={`img-ticket-solid-shadow-container ${model.isSmallScreen() ? "" : "mx-24"} px-6 pt-4 pb-6 text-accent-1 text-center`}
				>
					<L10n.Stylize
						text={"LOC_UI_SYNCRETISM_INSTRUCTIONS"}
						args={[civPeopleName(), civName()]}
					/>
				</div>
			</div>
			<div
				class={`w-full title-font text-center flex items-center tracking-100 justify-center flex-auto font-bold uppercase text-secondary ${model.isSmallScreen() ? "pb-5 pt-1" : "max-h-20 pb-5 pt-4 text-lg"} `}
			>
				<L10n.Compose text={"LOC_UI_SYNCRETISM_CHOOSE_ONE"} />
			</div>

			<div class="relative flex-auto">
				<div class="absolute w-full syncretism-body-bg-overlay -top-2 -bottom-2" />

				<ScrollArea class="relative">
					<SpatialSlot
						name="syncretism-choices"
						class={`flex flex-auto flex-wrap size-full ${model.isSmallScreen() && !isMobile() ? "justify-center" : ""}`}
					>
						<For each={model.data}>
							{(item) => (
								<AudioContextProvider segment="SyncretismCard">
									<Tab.Trigger name={"Syncretism-Confirm"}>
										<SyncCard
											style={
												isMobile()
													? { width: "48%", "margin-left": "0.85%", "margin-right": "0.85%" }
													: model.isSmallScreen()
														? { width: "95%" }
														: {
																width: "31.5%",
																"margin-left": "0.75%",
																"margin-right": "0.75%",
															}
											}
											civ={item.civ}
											civIcon={item.civIcon}
											class={`${model.isSmallScreen() && !isMobile() ? "mb-10 mr-5" : "mb-5"} mt-3`}
											itemsAvailable={item.itemsAvailable}
											civDef={item.civDef}
											flagType={item.flagType}
											traits={item.traits}
											bgImage={item.bgImage}
											isSyncretized={item.isSyncretized}
											hasSyncreticChoiceBeenMade={item.hasSyncreticChoiceBeenMade}
										/>
									</Tab.Trigger>
								</AudioContextProvider>
							)}
						</For>
					</SpatialSlot>
				</ScrollArea>
			</div>
		</div>
	);
};

export interface SyncretismScreenProps {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

const SyncretismScreenComponent: Component<SyncretismScreenProps> = (props) => {
	const model = SyncretismScreenModel.get();
	const audio = useAudio("SyncretismScreen");

	function handleCancelInput() {
		if (model.activeTab() == "syncretism-confirm") {
			model.setActiveTab("syncretism-choice");
			audio("popup-back");
		} else {
			model.clickCloseButton();
			audio("popup-close");
		}
	}

	return (
		<NestedTooltipContext.Provider value={{ disabled: true }}>
			<SyncretismScreenModelContext.Provider value={model}>
				<Panel
					ref={props.ref}
					name="Syncretism Screen"
					id="screen-syncretism"
					class={`bg-cover bg-no-repeat ${isMobile() ? "relative size-full" : "absolute top-8 bottom-2 right-4 left-4"}`}
					onCancelInput={handleCancelInput}
				>
					<AudioContextProvider segment="SyncretismScreen">
						<div class="absolute bg-cover bg-no-repeat syncretism-frame fullscreen-outside-safezone" />
						<div
							class={`${isMobile() ? "" : "m-1"} absolute bg-cover bg-no-repeat syncretism-bg opacity-20 fullscreen-outside-safezone`}
						/>
						<div
							class={`${isMobile() ? "" : "m-1"} absolute bg-cover bg-no-repeat syncretism-bg-gradient fullscreen-outside-safezone`}
						/>

						<Tab
							activeTab={model.activeTab}
							class="w-full relative flex flex-col flex-auto pointer-events-auto"
						>
							<Tab.Output />
							<Tab.Item
								name="syncretism-choice"
								title={() => "Syncretism"}
								body={() => (
									<SyncretismStartScreen
										ref={props.ref}
										name="LOC_UI_SYNCRETISM_TITLE"
										id="syncretism-choice"
									/>
								)}
							/>
							<Tab.Item
								name="Syncretism-Confirm"
								title={() => "Syncretism-Confirm"}
								body={() => (
									<SyncretismConfirm
										name="Syncretism-Confirm"
										screenId="screen-syncretism-confirm"
										selectedCiv={model.selectedCiv}
										isSmallScreen={model.isSmallScreen()}
									/>
								)}
							/>
							<CloseButton
								class={`${IsControllerActive() ? "hidden" : ""} absolute right-1 top-1`}
								onActivate={() => {
									audio("popup-close");
									model.clickCloseButton();
								}}
								hotkeyAction="cancel"
								navTrayText="LOC_GENERIC_BACK"
							/>
						</Tab>
					</AudioContextProvider>
				</Panel>
			</SyncretismScreenModelContext.Provider>
		</NestedTooltipContext.Provider>
	);
};

defineLegacyComponent(
	"screen-syncretism",
	{
		classNames: ["screen-syncretism", "fullscreen"],
		tabIndex: -0,
	},
	(_attrs, _element) => {
		Input.setActiveContext(InputContext.Shell);
		return <SyncretismScreenComponent />;
	},
);

export const SyncretismScreen = ComponentRegistry.register({
	name: "SyncretismScreen",
	styles: [style],
	createInstance: SyncretismScreenComponent,
});
